sp_widget.client_script:
api.controller = function ($scope, $location, $sce, $window) {
  var c = this;
  function sget(k, d) { try { return $window.localStorage.getItem(k) || d; } catch (e) { return d; } }
  function sset(k, v) { try { $window.localStorage.setItem(k, v); } catch (e) { } }
  var P = {
    home: 'M3 11l9-8 9 8M5 10v10h5v-6h4v6h5V10',
    flag: 'M5 21V4M5 4h11l-2 4 2 4H5',
    layers: 'M12 3l9 5-9 5-9-5 9-5zM3 13l9 5 9-5',
    target: 'M12 21a9 9 0 100-18 9 9 0 000 18zM12 16a4 4 0 100-8 4 4 0 000 8zM12 12h.01',
    bulb: 'M9 18h6M10 21h4M12 3a6 6 0 00-4 10.5c.7.7 1 1.5 1 2.5h6c0-1 .3-1.8 1-2.5A6 6 0 0012 3z',
    folder: 'M3 6a2 2 0 012-2h4l2 2h8a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V6z',
    org: 'M12 3v5M5 21v-5a2 2 0 012-2h10a2 2 0 012 2v5M12 8a2 2 0 100 4 2 2 0 000-4z',
    list: 'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',
    tag: 'M20 12l-8 8-9-9V4h7l10 8zM7.5 8.5h.01',
    grid: 'M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z',
    moon: 'M21 13A9 9 0 1111 3a7 7 0 0010 10z',
    sun: 'M12 17a5 5 0 100-10 5 5 0 000 10zM12 1v2M12 21v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M1 12h2M21 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4',
    user: 'M20 21a8 8 0 10-16 0M12 11a4 4 0 100-8 4 4 0 000 8z',
    key: 'M15 7a4 4 0 11-3.9 5L3 20v-3h3v-3h3l2.1-2.1A4 4 0 0115 7z',
    lock: 'M6 11h12v10H6zM8 11V7a4 4 0 118 0v4',
    dot: 'M12 12h.01'
  };
  c.icon = function (n) { return $sce.trustAsHtml('<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="' + (P[n] || P.dot) + '"/></svg>'); };
  c.ar = sget('vroLang', 'ar') === 'ar';
  c.dark = sget('vroTheme', 'light') === 'dark';
  c.lab = function (l) { return l ? ((c.ar ? l.ar : l.en) || l.en || '') : ''; };
  c.main = (c.data.items || []).filter(function (m) { return !m.more; });
  c.more = (c.data.items || []).filter(function (m) { return m.more; });
  c.cur = $location.search().id || 'vro_home';
  $scope.$on('$locationChangeSuccess', function () { c.cur = $location.search().id || 'vro_home'; c.moreOpen = false; c.userOpen = false; });
  c.moreOn = function () { return c.more.some(function (m) { return m.id === c.cur; }); };
  c.toggleLang = function () { sset('vroLang', c.ar ? 'en' : 'ar'); $window.location.reload(); };
  c.toggleTheme = function () { sset('vroTheme', c.dark ? 'light' : 'dark'); $window.location.reload(); };
  $window.document.addEventListener('click', function (e) { if (!e.target.closest || !e.target.closest('.vh-more, .vh-user')) { $scope.$applyAsync(function () { c.moreOpen = false; c.userOpen = false; }); } });
};

sp_widget.css:
.vh { --card: #ffffff; --head: #003462; --green: #1B8354; --soft: #E6F2EC; --text: #17304a; --muted: #64788a; --line: #e2eae6;
  position: relative; z-index: 100; background: rgba(255,255,255,.97); border-bottom: 1px solid var(--line); font-family: 'Segoe UI', Tahoma, Arial, sans-serif; color: var(--text); box-shadow: 0 4px 18px rgba(0,52,98,.06);
  a { text-decoration: none; cursor: pointer; }
  .vh-row { max-width: 1352px; margin: 0 auto; padding: 8px 12px; display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
  .vh-logo img { height: 44px; display: block; }
  .vh-pills { display: flex; gap: 4px; align-items: center; flex-wrap: wrap; flex: 1 1 auto; margin-inline-start: 10px; }
  .vh-pills > a, .vh-more > a { display: inline-flex; align-items: center; gap: 8px; padding: 10px 16px; border-radius: 99px; font-weight: 700; font-size: .95em; color: var(--head); }
  .vh-pills > a:hover, .vh-more > a:hover, .vh-menu a:hover { background: var(--soft); color: var(--green); }
  .vh-pills > a.on, .vh-more.on > a { background: var(--soft); color: var(--green); box-shadow: inset 0 -3px 0 var(--green); }
  .vh-i { display: inline-flex; }
  .vh-more { position: relative; }
  .vh-menu { position: absolute; top: calc(100% + 8px); inset-inline-start: 0; min-width: 230px; background: var(--card); border: 1px solid var(--line); border-radius: 18px; box-shadow: 0 18px 40px rgba(0,52,98,.18); padding: 8px; display: grid; gap: 2px; z-index: 200; }
  .vh-menu a { display: flex; align-items: center; gap: 10px; padding: 10px 14px; border-radius: 12px; color: var(--head); font-weight: 600; }
  .vh-menu a.on { background: var(--soft); color: var(--green); }
  .vh-out { color: #C0392B !important; }
  .vh-rt { display: flex; align-items: center; gap: 8px; margin-inline-start: auto; }
  .vh-btn { display: inline-flex; align-items: center; justify-content: center; height: 42px; min-width: 42px; padding: 0 14px; border-radius: 99px; border: 1.5px solid var(--line); background: var(--card); color: var(--head); font-weight: 700; }
  .vh-btn:hover { border-color: var(--green); color: var(--green); }
  .vh-ib { padding: 0; width: 42px; }
  .vh-user { position: relative; }
  .vh-av { display: inline-flex; width: 42px; height: 42px; border-radius: 50%; align-items: center; justify-content: center; font-weight: 800; font-size: 17px; color: #fff; background: linear-gradient(135deg, #1B8354, #23a068); }
  .vh-um { inset-inline-start: auto; inset-inline-end: 0; }
  .vh-who { padding: 10px 14px 8px; border-bottom: 1px solid var(--line); margin-bottom: 4px; display: grid; }
  .vh-who small { color: var(--muted); }
}
.vh.dark { --card: #152636; --head: #E8F1F8; --soft: #173b30; --text: #dbe7f1; --muted: #8fa6ba; --line: #26425b; background: rgba(11,24,36,.97); box-shadow: 0 4px 18px rgba(0,0,0,.4); }
@media (max-width: 900px) { .vh .vh-pills > a span:not(.vh-i), .vh .vh-more > a span:not(.vh-i) { display: none; } .vh .vh-pills > a, .vh .vh-more > a { padding: 10px; } .vh .vh-row { padding: 8px 12px; } .vh .vh-lang { display: none; } }

